require "rails_helper"

RSpec.describe Invoices::ReservationOutcome do
  # "Invoices::ReservationOutcome (state: prepared, committed, aborted, refused or retryable;
  # conflicts as a list of entry_id and reason; counts)"
  it "accepts only the five outcome states and refuses any other" do
    %w[prepared committed aborted refused retryable].each do |state|
      outcome = described_class.new(state:, conflicts: [{ entry_id: 7, reason: "not_found" }], counts: { reserved: 1 })

      expect(outcome.state).to eq(state)
      expect(outcome.conflicts).to eq([{ entry_id: 7, reason: "not_found" }])
    end

    %w[pending granted].each do |state|
      expect { described_class.new(state:, conflicts: [], counts: {}) }.to raise_error(ArgumentError)
    end
  end
end
